def get_paths():
    home = os.environ.get("HOME", "")
    xdg_config = os.environ.get("XDG_CONFIG_HOME", "")
    xdg_data = os.environ.get("XDG_DATA_HOME", "")
    if xdg_config is not None and xdg_config != "":
        config_path = os.path.join(xdg_config, "jot/config")
    else:
        config_path = os.path.join(home, ".config/jot/config")
    if xdg_data is not None and xdg_data != "":
        vaults_path = os.path.join(xdg_data, "jot/vaults")
    else:
        vaults_path = os.path.join(home, ".local/share/jot/vaults")
    return config_path, vaults_path

def ensure_files(config_path, vaults_path):
    # create parent dirs and files with defaults if missing
    for p, default in [(config_path, "editor = 'nvim'\nconflict = true\n"), (vaults_path, "[vaults]\n")]:
        parent = os.path.dirname(p)
        try:
            os.makedirs(parent, exist_ok=True)
        except Exception:
            pass
        if not os.path.exists(p):
            try:
                with open(p, 'w') as f:
                    f.write(default)
            except Exception:
                pass
        # if exists but is directory? then subsequent open will fail and panic? For now ignore.

def parse_toml_value(vstr):
    vstr = vstr.strip()
    if vstr.startswith("'''") and vstr.endswith("'''") and len(vstr) >= 6:
        return vstr[3:-3]
    if vstr.startswith("'") and vstr.endswith("'") and len(vstr) >= 2:
        # ensure not triple? already handled
        return vstr[1:-1]
    if vstr.startswith('"') and vstr.endswith('"') and len(vstr) >= 2:
        inner = vstr[1:-1]
        # unescape \" and \\ ?
        # simple: replace \\ with \, \" with "
        # TOML basic strings: handle common escapes
        res = ""
        i = 0
        while i < len(inner):
            if inner[i] == '\\' and i+1 < len(inner):
                nxt = inner[i+1]
                if nxt == 'n':
                    res += '\n'; i+=2; continue
                elif nxt == 't':
                    res += '\t'; i+=2; continue
                elif nxt == 'r':
                    res += '\r'; i+=2; continue
                elif nxt == '\\':
                    res += '\\'; i+=2; continue
                elif nxt == '"':
                    res += '"'; i+=2; continue
                elif nxt == 'u' and i+5 < len(inner):
                    try:
                        res += chr(int(inner[i+2:i+6],16)); i+=6; continue
                    except:
                        res += inner[i]; i+=1; continue
                else:
                    res += nxt; i+=2; continue
            else:
                res += inner[i]; i+=1
        return res
    if vstr == "true":
        return True
    if vstr == "false":
        return False
    if vstr == "[]":
        return []
    # handle [ ] with spaces?
    if vstr.startswith("[") and vstr.endswith("]"):
