    raise ValueError("unknown value")

def parse_key(kstr):
    kstr = kstr.strip()
    if kstr.startswith('"') and kstr.endswith('"') and len(kstr)>=2:
        inner = kstr[1:-1]
        # unescape
        res=""
        i=0
