                elif nxt=='n':
                    res+='\n'; i+=2; continue
                elif nxt=='t':
                    res+='\t'; i+=2; continue
                else:
                    res+=nxt; i+=2; continue
            else:
                res+=inner[i]; i+=1
        return res
    if kstr.startswith("'") and kstr.endswith("'") and len(kstr)>=2:
